N(bank,6,216,V,'Координатная плоскость и маршруты на сетке','16–17',[
('6-coord-ordinate','У точки A(−4; 7) найдите ординату.',7,'Ордината — вторая координата точки. Здесь она равна 7.','[-4,7][1]','b'),
('6-coord-axis-zero','Точка B лежит на оси ординат, её ордината −6. Найдите абсциссу B.',0,'У всех точек оси ординат абсцисса равна нулю.','0*(-6)','b'),
('6-coord-horizontal-length','На координатной плоскости A(−3; 2), B(5; 2). Найдите длину AB в единичных отрезках.',8,'Точки лежат на одной горизонтали. Расстояние равно разности абсцисс: 5 − (−3) = 8.','abs(5-(-3))','m'),
('6-coord-rectangle-fourth','Три последовательные вершины прямоугольника: A(−2; 1), B(4; 1), C(4; 5). Найдите сумму координат четвёртой вершины D.',3,'Четвёртая вершина D(−2; 5). Сумма координат −2 + 5 = 3.','-2+5','m'),
('6-coord-quadrants-count','Сколько точек из A(−2; 3), B(0; 4), C(5; −1), D(−3; −2), E(1; 1) лежит во второй четверти?',1,'Во второй четверти абсцисса отрицательна, ордината положительна. Подходит только A; точка B лежит на оси.','sum(x<0 and y>0 for x,y in [(-2,3),(0,4),(5,-1),(-3,-2),(1,1)])','m',{'tricky':True}),
('6-coord-manhattan-shortest','По линиям квадратной сетки нужно пройти из (−2; −1) в (3; 4). Шаг сетки 1 м. Найдите длину кратчайшего маршрута в метрах.',10,'Нужно сместиться на 5 м вправо и на 5 м вверх. Любой маршрут без обратных шагов имеет длину 10 м.','abs(3-(-2))+abs(4-(-1))','h'),
('6-coord-visit-axis','Робот стартует в (2; −3), делает 5 шагов влево, 4 вверх и 1 вправо. Найдите произведение координат конечной точки.',-2,'Абсцисса 2 − 5 + 1 = −2, ордината −3 + 4 = 1. Произведение −2.','(2-5+1)*(-3+4)','m'),
('6-coord-through-point-route','Кратчайший путь по линиям сетки из A(0; 0) в B(6; 4) обязан пройти через C(8; 2). Найдите длину пути при шаге сетки 1 м.',14,'От A до C нужно 8 + 2 = 10 шагов; от C до B — 2 + 2 = 4. Всего 14 м.','abs(8)+abs(2)+abs(6-8)+abs(4-2)','h'),
('6-coord-perimeter-from-opposites','Противоположные вершины прямоугольника со сторонами вдоль осей: (−4; −2) и (2; 3). Найдите его периметр.',22,'Длины сторон 6 и 5. Периметр 2 · (6 + 5) = 22.','2*(abs(2-(-4))+abs(3-(-2)))','h'),
('6-coord-integral-border','Сколько точек с целыми координатами лежит на границе квадрата с вершинами (0; 0), (3; 0), (3; 3), (0; 3)?',12,'На каждой стороне 4 точки, но четыре вершины посчитались дважды. Поэтому 4 · 4 − 4 = 12.','sum(x in [0,3] or y in [0,3] for x in range(4) for y in range(4))','s'),
('6-coord-return-final','Робот прошёл по сетке 7 клеток вправо, 3 вверх, 2 влево, 8 вниз и вернулся к началу кратчайшим путём. Сколько клеточных сторон он прошёл всего?',30,'Первая часть пути 20 шагов. Конечное смещение (5; −5), возврат требует 10 шагов. Всего 30.','7+3+2+8+abs(7-2)+abs(3-8)','s'),
('6-coord-distance-to-axis','Точка K имеет координаты (−8; 3). Найдите расстояние от K до оси абсцисс.',3,'К оси абсцисс идём вертикально. Длина такого отрезка равна модулю ординаты: |3| = 3.','abs(3)','b')])
N(bank,6,217,V,'Отрезки, лучи и измерение углов','17',[
('6-segment-midpoint-end','M — середина отрезка AB длиной 14,6 см. Найдите AM в сантиметрах.',7.3,'Середина делит отрезок пополам: 14,6 : 2 = 7,3 см.','F("14.6")/2','b'),
('6-angle-right-completion','Луч делит прямой угол на углы 34° и x°. Найдите x.',56,'Сумма частей прямого угла 90°. Значит x = 90 − 34 = 56.','90-34','b'),
('6-segment-order-three','Точки A, C, D, B лежат на прямой в указанном порядке. AB = 25 см, AC = 7 см, DB = 9 см. Найдите CD в сантиметрах.',9,'AB складывается из AC, CD и DB. Поэтому CD = 25 − 7 − 9 = 9 см.','25-7-9','m'),
('6-angle-full-turn-parts','Полный оборот разбит на три угла: 85°, 140° и x°. Найдите x.',135,'Полный оборот равен 360°. Остаток 360 − 85 − 140 = 135°.','360-85-140','m'),
('6-segment-two-midpoints','На отрезке AB длиной 24 см точка C такова, что AC = 8 см. M и N — середины AC и CB. Найдите MN в сантиметрах.',12,'AM = 4 см, CN = 8 см. Поэтому MN = MC + CN = 4 + 8 = 12 см.','8/2+(24-8)/2','h'),
('6-angle-bisector-difference','Луч OC внутри угла AOB образует с OA угол 24°, а с OB — 38°. Найдите угол между OC и биссектрисой AOB в градусах.',7,'Весь угол 62°, его половина 31°. Угол между OC и биссектрисой 31 − 24 = 7°.','abs((24+38)/2-24)','h'),
('6-segment-outside-branch','AB = 6 см, BC = 10 см, точки A, B, C лежат на одной прямой, причём B не лежит между A и C. Найдите AC в сантиметрах.',4,'Точка A должна лежать между B и C, поскольку BC больше AB. Поэтому AC = BC − AB = 4 см.','10-6','h',{'tricky':True}),
('6-angle-clock-hour','Какой меньший угол в градусах образуют стрелки часов ровно в 8:00?',120,'Между соседними часовыми отметками 30°. Кратчайшее расстояние от 8 до 12 — четыре промежутка, угол 120°.','min(8*30,360-8*30)','m'),
('6-angle-clock-halfhour','Найдите меньший угол между стрелками часов в 3:30, в градусах.',75,'Минутная стрелка на 180°, часовая на 3,5 · 30° = 105°. Разность 75°.','abs(180-(3+F(1,2))*30)','s'),
('6-segment-four-points-count','На прямой отметили 5 различных точек. Сколько разных отрезков с концами в этих точках можно назвать?',10,'Из каждой пары точек получается один отрезок. Можно считать по левому концу: 4 + 3 + 2 + 1 = 10.','len(list(combinations(range(5),2)))','h'),
('6-angle-protractor-offset','На транспортире один луч проходит через отметку 25°, второй — через отметку 117° той же шкалы. Найдите угол между ними в градусах.',92,'Нужно вычесть показания одной шкалы: 117 − 25 = 92°. Отсчёт не начинается от нуля.','117-25','m',{'tricky':True}),
('6-segment-pairwise-reconstruction','Три точки лежат на одной прямой. Два из трёх попарных расстояний равны 5 см и 13 см. Найдите сумму всех возможных значений третьего расстояния в сантиметрах.',26,'Третье расстояние может быть 13 − 5 = 8 см или 13 + 5 = 18 см. Сумма возможных значений 26 см.','(13-5)+(13+5)','s')])
